{
  "packet_id": "H6-T03-1",
  "claim_id": "C026",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C026.component",
    "value": "Patterns of discrepancies can constrain competing accounts of departures at distinct stages: obtaining approval, documenting it, linking it to the order or attaching it to the system.",
    "scope": "Constraint of competing process accounts, without an assertion that a unique account or a particular failure stage has been established.",
    "provenance": {
      "refs": [
        {
          "source_id": "P020",
          "role": "SUPPORT"
        },
        {
          "source_id": "P027",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P020 states the constrained-account inference and distinguishes the four stages; P027 explicitly preserves non-uniqueness."
    }
  },
  "signal_basis": {
    "component_id": "C026.signal_basis",
    "value": "Compare documentary links, timing and missing traces with candidate route predictions, observing whether approval records connect to particular orders, precede placement and establish appropriate authority, and whether discrepancies recur by route, role, period or record location.",
    "scope": "Proposed observations assumed to occur for this assessment. Interpretation must accommodate record limitations and legitimate workflow exceptions; the packet does not report these observations as established findings.",
    "provenance": {
      "refs": [
        {
          "source_id": "P011",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "SUPPORT"
        },
        {
          "source_id": "P026",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the comparison operation, observable discrepancies, proposed status and material limits on interpreting documentary patterns."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C026.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This component is inapplicable because the judgment is SUPPORTED, not CONDITIONAL_WARRANT."
    }
  },
  "rationale": "Observed links, timing and discontinuities can test the observable implications of competing process accounts and restrict which accounts fit the evidence. That licenses the claim's limited inference of constraint. It does not require identifying a unique history or establishing a particular failure stage, and the mapping explicitly retains documentary limitations and alternative histories.",
  "uncertainty": "Missing or unreliable records and equivalent surviving traces may leave several accounts viable. These limits affect how strongly the evidence constrains accounts without defeating the bounded claim.",
  "anomalies": []
}
